x_comment('x_Digging-FightingHole',"#$Digging-FightingHole is an instance of #$MilitaryEventType-Fundamental and a specialization of #$MilitaryEvent and #$DiggingAHole.  Each instance of #$Digging-FightingHole involves a military unit digging a #$FightingHole, which would provide cover to friendly troops while they engage the enemy.  Unlike a trench, a fighting hole is usually round and may only contain one or two soldiers.") :- x_cid(a65b1275334ad6).
