x_comment(x_regionHasSurfaceLevelInNumberOfDirections,"An instance of #$TernaryPredicate, used to describe the surface level of the ground on each of the four 'sides' of a  #$GeographicalRegion. (The number 4 is a simplifying assumption, consistent with military definitions of important terrain descriptions, used to make knowledge acquisition and representation easier.) (#$regionHasSurfaceLevelInNumberOfDirections REGION LEVEL NUM-SIDES) means that NUM-SIDES of REGION have are LEVEL. For example, (#$regionHasSurfaceLevelInNumberOfDirections Hill001 #$TerrainLowGround 4) means that Hill001 has low ground in (all) four directions. To specify how many sides that share this ground level are adjacent, use #$regionHasSurfaceLevelInNumberOfAdjacentDirections.  To specify this information for a type of region, use #$regionTypeHasSurfaceLevelInNumberOfDirections and #$regionTypeHasSurfaceLevelInNumberOfAdjacentDirections.") :- x_cid(a65b1275334adc).
xc_microtheory(a65b1275334adc,x_MilitaryGVocabularyMt).
