x_comment(x_operationalControlMilitaryOrg,"(#$operationalControlMilitaryOrg SUPER SUB) means that the organization SUPER has been given operational control (very temporary command) of the organization SUB for the duration of some operation.  This predicate corresponds to the concept known in military parlance as the 'OPCON' relation.  It is a 'direct' subordination-relation (with no intermediate levels of command between SUPER and SUB), entailing command of SUB by SUPER, and lasting, usually, only for the extent of the operation in question  (it is even more temporary than #$subOrgs-Temporary).  Often SUPER will not be responsible for logistical support of SUB, nor for paying SUB's expenses out of SUPER's regular budget.  See also #$assignedMilitaryOrg and #$attachedMilitaryOrg.") :- x_cid(a65b1275334aea).
xc_microtheory(a65b1275334aea,x_MilitaryGVocabularyMt).
xc_source_file(a65b1275334aea,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/MilitaryGVocabularyMt.krf').
