x_comment(x_MilitaryUnitTypeByEchelonSize,"An instance of #$SecondOrderCollection, and a faceting collection on #$ModernMilitaryOrganization.  In military parlance, there is a tendency to describe units by their size, relative to the typical sizes of echelons.  So a unit (of any echelon) might or might not be \"battalion-sized,\" \"brigade-sized,\" and so on.  Each instance of #$MilitaryUnitTypeByEchelonSize is a collection of instances of #$ModernMilitaryOrganization that all share a common size, typical of some particular echelon (c.f. #$MilitaryUnitTypeByEchelon).  See also #$MilitaryUnitTypeOfSizeFn, which can be used to reify instances of this collection on the fly.") :- x_cid(a65b1275334af6).
