x_comment(x_WeaponOfMassDestruction,"The collection of #$Weapons which have massive destructive power.  Deployment of these #$Weapons impacts a much larger area than conventional weapons and results in much more structural damage and/or loss of life. Damage caused by instances of #$WeaponOfMassDestruction is not specific; friendly troops, civilians, and plant and animal life are as likely to be harmed as the intended target.  #$Mine-Weapons are a borderline example in this collection.") :- x_cid(a65b1275334afd).
