x_comment(x_assignedMilitaryOrg,"(#$assignedMilitaryOrg SUPER SUB) means that the organization SUB is a permanently assigned immediate sub-organization of SUPER;  SUPER commands SUB, supports it logistically if need be, and provides the money for SUB's budget.  This predicate corresponds to the concept of permanent 'assignment' in a military command structure, as in Peterson and Andersen (1997).  This relationship entails financial, logistical, and command subordination; it is ordinarily a direct command relationship without intervening levels -- it is not transitive --and it is considered to be permanent (that is, a relationship has obtained historically and will continue to hold for the foreseeable future).  Most departments, subdivisions, branches, etc. of organizations are #$assignedMilitaryOrg.  See also #$attachedMilitaryOrg and #$operationalControlMilitaryOrg.") :- x_cid(a65b1275334b18).
xc_microtheory(a65b1275334b18,x_MilitaryGVocabularyMt).
xc_source_file(a65b1275334b18,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/MilitaryGVocabularyMt.krf').
