x_comment('x_Mine-Weapon',"A specialization of #$Bomb-ProximityTriggered.  Each instance of #$Mine-Weapon is a self-contained explosive device designed to be buried just under the ground surface or to be released in water. Mines have sensing and triggering mechanisms which detonate the #$ExplosiveDevices in the mine when something comes near it.  They are sown or released randomly to destroy a passing vehicle, ship, or human target without regard to allegiance or combatant status.  #$Mine-Weapons which are buried on the land are referred to as #$LandMines; those which are used in water are simply grouped under #$Mine-Weapons.") :- x_cid(a65b1275334b1d).
xc_microtheory(a65b1275334b1d,x_MilitaryGVocabularyMt).
