x_comment(x_weaponUsesAmmunitionInAttack,"(#$weaponUsesAmmunitionInAttack ATTACK WEAPON THING) holds iff, during an #$AttackOnTangible, a #$Weapon uses some #$PartiallyTangible as ammunition. The ammunition is 'used' primarily in the sense of being the arg2 of #$launchesProjectile, but also covers cases where the ammunition is stuff-like (e.g., #$Napalm) or simply energy (e.g., many #$Weapons in the #$PropositionalConceptualWork-ScienceFictionGenre).") :- x_cid(a65b1275334b21).
