x_comment(x_SupplementaryTerrainFeature,"An instance of #$TerrainTypeByMilitaryClassification.  Instances of #$SupplementaryTerrainFeature are man-made instances of #$LandTopographicalFeature that are considered \"supplementary\" for purposes of military operations.  By definition, instances of #$SupplementaryTerrainFeature are any of the the instances of #$MilitarySupplementaryTerrainType: Cut and Fill.") :- x_cid(a65b1275334b27).
xc_microtheory(a65b1275334b27,x_MilitaryGVocabularyMt).
xc_source_file(a65b1275334b27,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/MilitaryGVocabularyMt.krf').
