x_comment(x_BiologicalWeapon,"The collection of #$Weapons which contain a sample of biological agent (#$Bacterium, #$Virus, #$Fungus).  This collection includes body parts of plague victims catapulted into cities in the Middle Ages and smallpox infected blankets given to Native Americans, as well as crop-infecting sprays from \"crop dusting\" planes and purified bacterial strains released from explosive devices or sprayers.  Because these #$Weapons are inexpensive compared to traditional armaments, poor countries can compete with wealthy countries in the manufacture of such weapons and threatened use of them for deterrant purposes.") :- x_cid(a65b1275334b2f).
xc_microtheory(a65b1275334b2f,x_MilitaryGVocabularyMt).
xc_source_file(a65b1275334b2f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/MilitaryGVocabularyMt.krf').
