xc_mapping_rows(a65b1275334b2f,[]).
x_comment(x_MorningCivilTwilight,"Each #$MorningCivilTwilight begins when the #$Sun is six degrees           below the eastern horizon and ends at #$Sunrise.  At this time, there is           enough light to see objects clearly with the unaided eye.  Light intensification           devices are no longer effective.") :- x_cid(a65b1275334b30).
xc_microtheory(a65b1275334b30,x_MilitaryGVocabularyMt).
xc_source_file(a65b1275334b30,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/MilitaryGVocabularyMt.krf').
