xc_mapping_rows(a65b1275334b30,[]).
x_comment(x_AntiWeaponTypeFn,"For each TYPE in #$MilitaryWeaponTypeByFunction, (#$AntiWeaponTypeFn TYPE) is a collection containing all members of #$Artifact (and in most cases, members of #$MilitaryHardware or #$MilitaryWeapon) each of which has a main function against a main function of members of TYPE.  For example, all members of #$FighterPlane have a function of attacking #$BomberPlanes in the air, which is against one of main functions of #$BomberPlanes to attack targets on land or ocean from the air.  Thus #$FighterPlane is a subcollection of (#$AntiWeaponTypeFn #$BomberPlane).  Note in many cases, TYPE can be a subcollection of (#$AntiWeaponTypeFn TYPE), such as #$FighterPlane, #$Submarine, #$Tank-Vehicle, #$Cruiser and many other collections.") :- x_cid(a65b1275334b31).
xc_microtheory(a65b1275334b31,x_MilitaryGVocabularyMt).
xc_source_file(a65b1275334b31,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/MilitaryGVocabularyMt.krf').
xc_source_line(a65b1275334b31,367).
xc_kb_names(a65b1275334b31,[]).
xc_mapping_rows(a65b1275334b31,[]).
x_comment('x_Digging-Trench',"#$Digging-Trench is an instance of #$MilitaryEventType-Fundamental and a specialization of #$MilitaryEvent and #$DiggingAHole.  Each instance of #$Digging-Trench involves a military unit digging a #$Trench, which would protect and hide friendly troops from the enemy.  Unlike a mere hole, a trench is long, narrow, and usually steep-sided.") :- x_cid(a65b1275334b32).
xc_microtheory(a65b1275334b32,x_MilitaryGVocabularyMt).
